/**
 * Detect Track Changes
 *
 * Flujo esperado:
 *
 * Track Summary
 *   ↓
 * Get Previous Track Audit
 *   ↓
 * Detect Track Changes
 *   ↓
 * Save Track Audit
 *   ↓
 * Mark Event Processed
 *   ↓
 * Respond
 *
 * El nodo compara el estado ACTUAL de la pista contra
 * la ÚLTIMA versión auditada ANTERIOR.
 */

// ------------------------------------------------------------
// INPUTS
// ------------------------------------------------------------

const current = $('Track Summary').item.json;
const previous = $json ?? {};

// ------------------------------------------------------------
// NORMALIZACIÓN
// ------------------------------------------------------------

function normalizeNullable(value) {
  if (
    value === null ||
    value === undefined
  ) {
    return null;
  }

  if (
    typeof value === 'string' &&
    value.trim().toLowerCase() === 'null'
  ) {
    return null;
  }

  return value;
}

function normalizeNumber(value) {
  const normalized = normalizeNullable(value);

  if (normalized === null) {
    return null;
  }

  const number = Number(normalized);

  return Number.isFinite(number)
    ? number
    : null;
}

function normalizeString(value) {
  const normalized = normalizeNullable(value);

  if (normalized === null) {
    return null;
  }

  return String(normalized);
}

// ------------------------------------------------------------
// COMPARACIÓN
// ------------------------------------------------------------

function sameValue(a, b) {
  const left = normalizeNullable(a);
  const right = normalizeNullable(b);

  // Ambos vacíos
  if (
    left === null &&
    right === null
  ) {
    return true;
  }

  // Si uno es null y el otro no
  if (
    left === null ||
    right === null
  ) {
    return false;
  }

  // Comparación numérica
  if (
    typeof left === 'number' ||
    typeof right === 'number'
  ) {
    const leftNumber =
      normalizeNumber(left);

    const rightNumber =
      normalizeNumber(right);

    if (
      leftNumber === null &&
      rightNumber === null
    ) {
      return true;
    }

    if (
      leftNumber === null ||
      rightNumber === null
    ) {
      return false;
    }

    return (
      leftNumber === rightNumber
    );
  }

  // Comparación de strings/valores simples
  return (
    String(left) === String(right)
  );
}

function hasChanged(
  currentValue,
  previousValue,
) {
  return !sameValue(
    currentValue,
    previousValue,
  );
}

// ------------------------------------------------------------
// EXISTENCIA DE ESTADO ANTERIOR
// ------------------------------------------------------------

const hasPrevious =
  Boolean(
    normalizeNullable(
      previous.previous_event_id,
    ),
  );

// ------------------------------------------------------------
// ESTADO ANTERIOR NORMALIZADO
// ------------------------------------------------------------

const previousState = {
  eventId:
    normalizeString(
      previous.previous_event_id,
    ),

  title:
    normalizeString(
      previous.previous_title,
    ),

  artist:
    normalizeNullable(
      previous.previous_artist,
    ),

  album:
    normalizeNullable(
      previous.previous_album,
    ),

  genre:
    normalizeNullable(
      previous.previous_genre,
    ),

  key:
    normalizeNullable(
      previous.previous_key,
    ),

  remixer:
    normalizeNullable(
      previous.previous_remixer,
    ),

  bpm:
    normalizeNumber(
      previous.previous_bpm,
    ),

  rating:
    normalizeNumber(
      previous.previous_rating,
    ),

  lengthSeconds:
    normalizeNumber(
      previous.previous_length_seconds,
    ),

  bitrate:
    normalizeNumber(
      previous.previous_bitrate,
    ),

  sampleRate:
    normalizeNumber(
      previous.previous_sample_rate,
    ),

  playCount:
    normalizeNumber(
      previous.previous_play_count,
    ),

  rbLocalUsn:
    normalizeNumber(
      previous.previous_rb_local_usn,
    ),

  trackHash:
    normalizeString(
      previous.previous_track_hash,
    ),
};

// ------------------------------------------------------------
// ESTADO ACTUAL NORMALIZADO
// ------------------------------------------------------------

const currentState = {
  title:
    normalizeString(
      current.title,
    ),

  artist:
    normalizeNullable(
      current.artist,
    ),

  album:
    normalizeNullable(
      current.album,
    ),

  genre:
    normalizeNullable(
      current.genre,
    ),

  key:
    normalizeNullable(
      current.key,
    ),

  remixer:
    normalizeNullable(
      current.remixer,
    ),

  bpm:
    normalizeNumber(
      current.bpm,
    ),

  rating:
    normalizeNumber(
      current.rating,
    ),

  lengthSeconds:
    normalizeNumber(
      current.lengthSeconds,
    ),

  bitrate:
    normalizeNumber(
      current.bitrate,
    ),

  sampleRate:
    normalizeNumber(
      current.sampleRate,
    ),

  playCount:
    normalizeNumber(
      current.playCount,
    ),

  rbLocalUsn:
    normalizeNumber(
      current.rbLocalUsn,
    ),

  trackHash:
    normalizeString(
      current.trackHash,
    ),
};

// ------------------------------------------------------------
// DETECCIÓN DE CAMBIOS
//
// Si no hay snapshot anterior:
//   todos los cambios de negocio = false
//
// No podemos afirmar que algo "cambió" sin
// una versión anterior contra la cual comparar.
// ------------------------------------------------------------

const changes = {
  titleChanged:
    hasPrevious
      ? hasChanged(
          currentState.title,
          previousState.title,
        )
      : false,

  artistChanged:
    hasPrevious
      ? hasChanged(
          currentState.artist,
          previousState.artist,
        )
      : false,

  albumChanged:
    hasPrevious
      ? hasChanged(
          currentState.album,
          previousState.album,
        )
      : false,

  genreChanged:
    hasPrevious
      ? hasChanged(
          currentState.genre,
          previousState.genre,
        )
      : false,

  keyChanged:
    hasPrevious
      ? hasChanged(
          currentState.key,
          previousState.key,
        )
      : false,

  remixerChanged:
    hasPrevious
      ? hasChanged(
          currentState.remixer,
          previousState.remixer,
        )
      : false,

  bpmChanged:
    hasPrevious
      ? hasChanged(
          currentState.bpm,
          previousState.bpm,
        )
      : false,

  ratingChanged:
    hasPrevious
      ? hasChanged(
          currentState.rating,
          previousState.rating,
        )
      : false,

  lengthChanged:
    hasPrevious
      ? hasChanged(
          currentState.lengthSeconds,
          previousState.lengthSeconds,
        )
      : false,

  bitrateChanged:
    hasPrevious
      ? hasChanged(
          currentState.bitrate,
          previousState.bitrate,
        )
      : false,

  sampleRateChanged:
    hasPrevious
      ? hasChanged(
          currentState.sampleRate,
          previousState.sampleRate,
        )
      : false,

  playCountChanged:
    hasPrevious
      ? hasChanged(
          currentState.playCount,
          previousState.playCount,
        )
      : false,

  // Cambio técnico; NO se considera cambio de negocio.
  trackHashChanged:
    hasPrevious
      ? hasChanged(
          currentState.trackHash,
          previousState.trackHash,
        )
      : false,

  // También queda disponible para diagnóstico.
  rbLocalUsnChanged:
    hasPrevious
      ? hasChanged(
          currentState.rbLocalUsn,
          previousState.rbLocalUsn,
        )
      : false,
};

// ------------------------------------------------------------
// CAMPOS DE NEGOCIO
//
// Deliberadamente excluimos:
//   trackHashChanged
//   rbLocalUsnChanged
//
// porque ambos pueden cambiar como consecuencia de un
// cambio real y no deben disparar automatizaciones por sí solos.
// ------------------------------------------------------------

const BUSINESS_CHANGE_FIELDS = [
  'titleChanged',
  'artistChanged',
  'albumChanged',
  'genreChanged',
  'keyChanged',
  'remixerChanged',
  'bpmChanged',
  'ratingChanged',
  'lengthChanged',
  'bitrateChanged',
  'sampleRateChanged',
  'playCountChanged',
];

const changedFields =
  BUSINESS_CHANGE_FIELDS
    .filter(
      (field) =>
        changes[field] === true,
    )
    .map(
      (field) =>
        field.replace(
          /Changed$/,
          '',
        ),
    );

// ------------------------------------------------------------
// ESTADO GENERAL
// ------------------------------------------------------------

const hasChanges =
  hasPrevious &&
  changedFields.length > 0;

// ------------------------------------------------------------
// RESUMEN HUMANO
// ------------------------------------------------------------

let changeSummary;

if (!hasPrevious) {
  changeSummary =
    'No previous audit state available';
} else if (!hasChanges) {
  changeSummary =
    'No tracked business field changes detected';
} else {
  changeSummary =
    `Changed: ${changedFields.join(', ')}`;
}

// ------------------------------------------------------------
// CAMBIOS DETALLADOS
// ------------------------------------------------------------

const changeDetails = {};

for (
  const field of BUSINESS_CHANGE_FIELDS
) {
  if (
    changes[field] === true
  ) {
    const baseField =
      field.replace(
        /Changed$/,
        '',
      );

    changeDetails[baseField] = {
      previous:
        previousState[
          baseField ===
          'length'
            ? 'lengthSeconds'
            : baseField
        ] ?? null,

      current:
        currentState[
          baseField ===
          'length'
            ? 'lengthSeconds'
            : baseField
        ] ?? null,
    };
  }
}

// ------------------------------------------------------------
// OUTPUT
// ------------------------------------------------------------

return [
  {
    json: {
      ...current,

      hasPrevious,

      previousState,

      currentState,

      changes,

      changedFields,

      changeDetails,

      hasChanges,

      changeSummary,
    },
  },
];

const current = $('Detect Track Changes').item.json;

const changedFields = Array.isArray(current.changedFields)
  ? current.changedFields
  : [];

const changesToLog = [];

for (const field of changedFields) {
  const details = current.changeDetails?.[field] ?? {};

  changesToLog.push({
    field_name: field,

    previous_value:
      details.previous == null
        ? null
        : String(details.previous),

    current_value:
      details.current == null
        ? null
        : String(details.current),
  });
}

return [
  {
    json: {
      ...current,

      changesToLog,

      shouldLogChanges:
        changesToLog.length > 0,
    },
  },
];

const current = $('Detect Track Changes').item.json;

const jobs = [];
const changes = current.changes ?? {};
const changedFields = Array.isArray(current.changedFields)
  ? current.changedFields
  : [];

const intelligenceFields = [
  'title',
  'artist',
  'album',
  'genre',
  'key',
  'remixer',
  'bpm',
  'length',
  'bitrate',
  'sampleRate',
];

const intelligenceChanged =
  !current.hasPrevious ||
  intelligenceFields.some((field) => changedFields.includes(field));

const preferenceChanged =
  changes.ratingChanged === true ||
  changes.playCountChanged === true;

const basePayload = {
  schemaVersion: 1,
  eventId: current.eventId,
  eventType: current.eventType,
  deviceId: current.deviceId,
  trackId: current.trackId,
  trackUuid: current.trackUuid,
  trackHash: current.trackHash,
  rbLocalUsn: current.rbLocalUsn,
  changedFields,
  changeDetails: current.changeDetails ?? {},
  currentState: current.currentState ?? {},
  previousState: current.previousState ?? null,
};

if (intelligenceChanged) {
  jobs.push({
    job_key: `${current.deviceId}:${current.trackId}:track.intelligence.refresh:${current.trackHash ?? current.rbLocalUsn}`,
    job_type: 'track.intelligence.refresh',
    priority: 50,
    event_id: current.eventId,
    device_id: current.deviceId,
    track_id: current.trackId,
    rb_local_usn: current.rbLocalUsn,
    payload: {
      ...basePayload,
      reason: current.hasPrevious ? 'tracked_field_changed' : 'initial_track_snapshot',
    },
  });
}

if (preferenceChanged) {
  jobs.push({
    job_key: `${current.deviceId}:${current.trackId}:track.preference.update:${current.eventId}`,
    job_type: 'track.preference.update',
    priority: 40,
    event_id: current.eventId,
    device_id: current.deviceId,
    track_id: current.trackId,
    rb_local_usn: current.rbLocalUsn,
    payload: {
      ...basePayload,
      reason: 'rating_or_play_count_changed',
      ratingChanged: changes.ratingChanged === true,
      playCountChanged: changes.playCountChanged === true,
    },
  });
}

return [{
  json: {
    ...current,
    intelligenceJobs: jobs,
    intelligenceJobCount: jobs.length,
  },
}];
